import sys
import os

def main():
    token = sys.stdin.readline().strip()
    template_path = sys.stdin.readline().strip()

    if not os.path.exists(template_path):
        print("ACCESS_DENIED")
        sys.exit(1)

    names = {}
    for line in sys.stdin:
        if '=' in line:
            name, value = line.strip().split('=', 1)
            names[name.strip()] = int(value.strip())

    access_token = None
    with open('access.txt', 'r') as f:
        first_line = f.readline().strip()
        if first_line.startswith(token + ':render'):
            access_token = first_line
        else:
            print("ACCESS_DENIED")
            sys.exit(1)

    with open(template_path, 'r') as f:
        template = f.read()

    def evaluate_expression(expr):
        stack = []
        i = 0
        n = len(expr)
        while i < n:
            if expr[i] == ' ':
                i += 1
                continue
            if expr[i] == '(':
                stack.append('(')
                i += 1
            elif expr[i] == ')':
                if not stack or stack[-1] != '(':
                    raise ValueError("Mismatched parentheses")
                stack.pop()
                i += 1
            elif expr[i] in '+-':
                stack.append(expr[i])
                i += 1
            else:
                num = ''
                while i < n and expr[i].isdigit():
                    num += expr[i]
                    i += 1
                if num:
                    stack.append(num)
        # Process the stack
        while len(stack) > 1:
            if stack[-2] == '+':
                right = stack.pop()
                left = stack.pop()
                stack.append(str(int(left) + int(right)))
            elif stack[-2] == '-':
                right = stack.pop()
                left = stack.pop()
                stack.append(str(int(left) - int(right)))
            else:
                raise ValueError("Invalid operator")
        return stack[0] if stack else '0'

    def replace_placeholders(text):
        result = []
        i = 0
        n = len(text)
        while i < n:
            if text[i] == '{' and i + 1 < n and text[i+1] == '{':
                j = text.find('}}', i)
                if j == -1:
                    result.append(text[i:])
                    break
                expr = text[i+2:j]
                try:
                    value = evaluate_expression(expr)
                    result.append(value)
                except:
                    result.append('{{' + expr + '}}')
                i = j + 2
            else:
                result.append(text[i])
                i += 1
        return ''.join(result)

    output = replace_placeholders(template)
    print(output)

if __name__ == "__main__":
    main()
